GlobalizationManagement = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=GlobalizationManagement");

        var ds = await model.getDatasource({ endpoint: "B2B/Country" });
        var countryGrid = new GridWidget($("[name=countryGrid]", container), ds)
        countryGrid.groupable = false;
        countryGrid.filterable = true;
        countryGrid.toolbar = "<button name='add'>[resource_displayname[add]]</button>";
        countryGrid.columns = [{ field: "Id" }, { field: "Name" }, { field: "InEuropeanUnion" }];
        countryGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        countryGrid.dataBound = function () {
            $("a[name=save]", countryGrid.gridElement).on("click", async function (e) {
                await GlobalizationManagement.save(e, countryGrid.kendoObject);
            });
        };
        await countryGrid.init();
        $("[name=add]", countryGrid.gridElement).on("click", async function (e) {
            await GlobalizationManagement.addCountry(e, countryGrid.kendoObject);
        });
        var ds = await model.getDatasource({ endpoint: "B2B/Currency" });
        var currencyGrid = new GridWidget($("[name=currencyGrid]", container), ds)
        currencyGrid.groupable = false;
        currencyGrid.filterable = true;
        currencyGrid.toolbar = "<button name='add'>[resource_displayname[add]]</button>";
        currencyGrid.columns = [{ field: "Id" }, { field: "Name" }];
        currencyGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        currencyGrid.dataBound = function () {
            $("a[name=save]", currencyGrid.gridElement).on("click", async function (e) {
                await GlobalizationManagement.save(e, currencyGrid.kendoObject);
            })
        };
        await currencyGrid.init();
        $("[name=add]", currencyGrid.gridElement).on("click", async function (e) {
            await GlobalizationManagement.addCurrency(e, currencyGrid.kendoObject);
        });
    },

    addCountry: async function (e, grid) {
        e.preventDefault();
        var d = new Dialog({ title: "[resource_displayname[addCountry]]", width: 600, height: 200 });
        d.template = $("[name=addCountryDialog]").html();
        d.events.add = async function () {
            var newCountry = {
                Id: $("[name=id]", d.element).val(),
                Name: $("[name=name]", d.element).val(),
                InEuropeanUnion: $("[name=inEU]", d.element).is(":checked")
            };
            await api.add("B2B/Country", newCountry).then(() => {
                notification.success("[resource_displayname[CountryAdded]]");
            }).catch((err) => { error(err); });
            grid.dataSource.read();
            d.events.close();
        };
        d.init();
    },

        addCurrency: async function (e, grid) {
        e.preventDefault();
        var d = new Dialog({ title: "[resource_displayname[addCurrency]]", width: 600, height: 160 });
        d.template = $("[name=addCurrencyDialog]").html();
        d.events.add = async function () {
            var newCurrency = {
                Id: $("[name=id]", d.element).val(),
                Name: $("[name=name]", d.element).val(),
            };
            await api.add("B2B/Currency", newCurrency).then(() => {
                notification.success("[resource_displayname[Currency]]");
            }).catch((err) => { error(err); });
            grid.dataSource.read();
            d.events.close();
        };
        d.init();
    },

    save: async function (e, grid) {
        e.preventDefault();
        var country = grid.dataItem($(e.currentTarget).closest("tr"));
        await country.save().then(() => {
            notification.success("[resource_displayname[CountrySaved]]");
        }).catch((err) => { error(err); });
    },

}
